{"path": "/app/bin/fees.py", "content": "#!/usr/bin/env python3
"""Overdue fee statements. Usage: fees.py INPUT_DIR OUTPUT_FILE"""
import configparser
import csv
import json
import os
import re
import sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP

DAY = timedelta(days=1)
WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]


def digits(p):
    d = re.sub(r"\D", "", p or "")
    return int(d) if d else 0


def pdate(s):
    return date.fromisoformat(s.strip())


def cents(s):
    return int((Decimal(s.strip()) * 100).quantize(Decimal(1), rounding=ROUND_HALF_UP))


def parse_offset(s):
    s = s.strip()
    m = re.fullmatch(r"([+-])(\d{1,2}):?(\d{2})?", s)
    sign = -1 if m.group(1) == "-" else 1
    return sign * timedelta(hours=int(m.group(2)), minutes=int(m.group(3) or 0))


def read_csv(path):
    with open(path, encoding="utf-8-sig", newline="") as f:
        return list(csv.DictReader(f))


def main(indir, outfile):
    # ---- policy
    cp = configparser.RawConfigParser(inline_comment_prefixes=None)
    cp.optionxform = str
    with open(os.path.join(indir, "policy.ini"), encoding="utf-8-sig") as f:
        cp.read_file(f)
    library = cp.get("statement", "library").strip()
    pstart = pdate(cp.get("statement", "period_start"))
    pend = pdate(cp.get("statement", "period_end"))
    base_off = parse_offset(cp.get("clock", "offset"))
    changes = []
    if cp.has_option("clock", "changes"):
        for part in cp.get("clock", "changes").split(";"):
            part = part.strip()
            if not part:
                continue
            inst, off = part.split()
            t = datetime.strptime(inst, "%Y-%m-%dT%H:%MZ").replace(tzinfo=timezone.utc)
            changes.append((t, parse_offset(off)))
    changes.sort(key=lambda c: c[0])

    items = {}
    cats = {}
    item_names = {}
    cat_names = {}
    for sec in cp.sections():
        if sec.lower().startswith("item:"):
            nm = sec[5:].strip()
            g = lambda k: cp.get(sec, k).strip()
            items[nm.lower()] = dict(
                loan_days=int(g("loan_days")), renewals=int(g("renewals")),
                grace=int(g("grace_days")), daily=cents(g("daily")), cap=cents(g("loan_cap")))
            item_names[nm.lower()] = nm
        elif sec.lower().startswith("category:"):
            nm = sec[9:].strip()
            sc = cp.get(sec, "statement_cap").strip()
            disc = cp.get(sec, "discount").strip().rstrip("%").strip()
            ex = cp.get(sec, "exempt").strip() if cp.has_option(sec, "exempt") else ""
            cats[nm.lower()] = dict(
                cap=None if sc.lower() == "none" else cents(sc),
                discount=int(disc or 0),
                exempt={x.strip().lower() for x in ex.split(",") if x.strip()})
            cat_names[nm.lower()] = nm

    # ---- branches, calendar
    branches = []
    open_days = {}
    canon = {}
    for r in read_csv(os.path.join(indir, "branches.csv")):
        b = r["branch"].strip()
        branches.append(b)
        canon[b.lower()] = b
        open_days[b] = {w.lower()[:3] for w in r["open_days"].split()}
    cal_branch = {b: [] for b in branches}
    cal_star = []
    for r in read_csv(os.path.join(indir, "calendar.csv")):
        ds = r["date"].strip()
        if ".." in ds:
            a, z = ds.split("..")
            a, z = pdate(a), pdate(z)
        else:
            a = z = pdate(ds)
        st = r["status"].strip().lower() == "open"
        br = r["branch"].strip()
        if br == "*":
            cal_star.append((a, z, st))
        else:
            cal_branch.setdefault(canon.get(br.lower(), br), []).append((a, z, st))

    def is_open(b, d):
        for a, z, st in cal_branch.get(b, ()):
            if a <= d <= z:
                return st
        for a, z, st in cal_star:
            if a <= d <= z:
                return st
        return WEEKDAYS[d.weekday()] in open_days.get(b, ())

    def next_open(b, d):
        while not is_open(b, d):
            d += DAY
        return d

    # ---- patrons
    patron_rows = {}
    for r in read_csv(os.path.join(indir, "patrons.csv")):
        patron_rows.setdefault(digits(r["patron"]), []).append(
            (pdate(r["since"]), r["category"].strip(), r["patron"].strip()))
    for v in patron_rows.values():
        v.sort(key=lambda x: x[0])

    def patron_at(num, d):
        best = None
        for row in patron_rows[num]:
            if row[0] <= d:
                best = row
        if best is None:
            best = patron_rows[num][0]
        return best

    # ---- waivers
    waivers = {}
    for r in read_csv(os.path.join(indir, "waivers.csv")):
        if r["status"].strip().lower() != "active":
            continue
        v = r["value"].strip()
        val = "full" if v.lower() == "full" else cents(v)
        waivers.setdefault(digits(r["patron"]), []).append((r["loan"].strip(), val))

    # ---- events
    def local_from_instant(s):
        s = s.strip()
        if s.endswith(("Z", "z")):
            s = s[:-1] + "+00:00"
        dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        utc = dt.astimezone(timezone.utc)
        off = base_off
        for t, o in changes:
            if t <= utc:
                off = o
        return (utc + off).replace(tzinfo=None)

    events = {}
    exdir = os.path.join(indir, "exports")
    for name in sorted(os.listdir(exdir)):
        path = os.path.join(exdir, name)
        if not os.path.isfile(path):
            continue
        rows = []
        if name.endswith(".csv"):
            for r in read_csv(path):
                r = {k: (v or "").strip() for k, v in r.items() if k is not None}
                if not r.get("event"):
                    continue
                r["_local"] = datetime.strptime(r["time"], "%Y-%m-%d %H:%M")
                rows.append(r)
        elif name.endswith(".jsonl"):
            with open(path, encoding="utf-8-sig") as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    o = json.loads(line)
                    r = {k: ("" if v is None else str(v).strip()) for k, v in o.items()}
                    r["_local"] = local_from_instant(r["at"])
                    rows.append(r)
        for r in rows:
            events.setdefault(r["event"], r)

    cancelled = set()
    for e in events.values():
        if e.get("type", "").lower() == "void" and e.get("target"):
            cancelled.add(e["target"])

    checkouts = {}
    others = {}
    for eid, e in events.items():
        if eid in cancelled:
            continue
        t = e.get("type", "").lower()
        if t == "checkout":
            checkouts[e["loan"]] = e
        elif t in ("renew", "return"):
            others.setdefault(e["loan"], []).append((e["_local"], t, e))

    # ---- loans
    loans = []
    for lid, c in checkouts.items():
        cdate = c["_local"].date()
        if cdate > pend:
            continue
        it = items[c["item_type"].lower()]
        b = canon.get(c["branch"].lower(), c["branch"])
        due = next_open(b, cdate + timedelta(days=it["loan_days"]))
        nren = 0
        ret = None
        for lt, t, e in sorted(others.get(lid, []), key=lambda x: x[0]):
            ld = lt.date()
            if t == "renew":
                if ld <= due and nren < it["renewals"] and ld <= pend:
                    nren += 1
                    due = next_open(b, ld + timedelta(days=it["loan_days"]))
            else:
                ret = ld
                if (e.get("via", "").lower()) == "dropbox":
                    ret -= DAY
                break
        if ret is not None and ret < pstart:
            continue
        still_out = ret is None or ret > pend
        end = pend if still_out else ret
        od = 0
        d = due + DAY
        while d <= end:
            if is_open(b, d):
                od += 1
            d += DAY
        if od == 0:
            continue
        num = digits(c["patron"])
        charged = od if od > it["grace"] else 0
        _, cat, _ = patron_at(num, cdate)
        cinfo = cats[cat.lower()]
        fee = charged * it["daily"]
        if c["item_type"].lower() in cinfo["exempt"]:
            fee = 0
        fee = min(fee, it["cap"])
        assessed = (fee * (100 - cinfo["discount"]) + 50) // 100
        loans.append(dict(
            num=num, loan=lid, item=c["item"], item_type=item_names[c["item_type"].lower()],
            branch=b, checkout=cdate, due=due, returned=None if still_out else ret,
            overdue_days=od, charged_days=charged, assessed=assessed))

    # ---- waivers and statement cap
    by_patron = {}
    for l in loans:
        by_patron.setdefault(l["num"], []).append(l)
        ws = [v for (lid, v) in waivers.get(l["num"], []) if lid == "*" or lid == l["loan"]]
        if any(v == "full" for v in ws):
            w = l["assessed"]
        else:
            w = min(sum(ws), l["assessed"])
        l["waived"] = w
        l["net"] = l["assessed"] - w
        l["capped"] = 0

    statements = []
    for num in sorted(by_patron):
        ls = by_patron[num]
        _, cat, pname = patron_at(num, pend)
        cap = cats[cat.lower()]["cap"]
        if cap is not None:
            excess = sum(l["net"] for l in ls) - cap
            if excess > 0:
                for l in sorted(ls, key=lambda x: (x["due"], x["loan"]), reverse=True):
                    take = min(l["net"], excess)
                    l["capped"] = take
                    excess -= take
                    if excess <= 0:
                        break
        for l in ls:
            l["billed"] = l["net"] - l["capped"]
        ls.sort(key=lambda x: (x["due"], x["loan"]))
        out_loans = []
        for l in ls:
            out_loans.append({
                "loan": l["loan"], "item": l["item"], "item_type": l["item_type"],
                "branch": l["branch"], "checkout": l["checkout"].isoformat(),
                "due": l["due"].isoformat(),
                "returned": l["returned"].isoformat() if l["returned"] else None,
                "overdue_days": l["overdue_days"], "charged_days": l["charged_days"],
                "assessed": l["assessed"], "waived": l["waived"],
                "capped": l["capped"], "billed": l["billed"]})
        st = {"patron": pname, "category": cat_names[cat.lower()], "loans": out_loans}
        for k in ("assessed", "waived", "capped", "billed"):
            st[k] = sum(x[k] for x in out_loans)
        statements.append(st)

    summary = []
    for b in branches:
        row = {"branch": b, "loans": 0, "charged_days": 0, "assessed": 0,
               "waived": 0, "capped": 0, "billed": 0}
        for l in loans:
            if l["branch"] == b:
                row["loans"] += 1
                for k in ("charged_days", "assessed", "waived", "capped", "billed"):
                    row[k] += l[k]
        summary.append(row)

    result = {"library": library,
              "period": {"start": pstart.isoformat(), "end": pend.isoformat()},
              "statements": statements, "branches": summary}
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(result, f, indent=2, ensure_ascii=False)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
